#!/usr/local/bin/prhm-node
'use strict';
const crypto=require('node:crypto');
const fs=require('node:fs');
const path=require('node:path');
const cp=require('node:child_process');
const ACTION='recovery_edge_topology_probe_v1';
const OPERATION='host_action.recovery_edge_topology_probe_v1';
const POLICY_VERSION='2026-09-15.1-recovery-edge-topology-probe-v1';
const PATHS=Object.freeze({base:'/opt/prhm-agent-selfmaint/server.js',exec:'/opt/prhm-agent-selfmaint-exec/server.js',policy:'/opt/prhm-company-control-plane/config/approval-policy.json',mcp:'/home/agent/ssh-mcp-server/src/plugins/hostActionsV2.js',helper:'/opt/prhm-agent-selfmaint-exec/actions/recovery-edge-topology-probe-v1.js'});
const BASELINE=Object.freeze({base:null,exec:null,policy:null,mcp:null});
const BASELINE_LOCKED=false;
const HELPER_SHA='31717f9600d96b3ad50ce56a425b56f41f5851c1c2a2b0502e870e2ee090ab90';
const HELPER_B64='';
const sha=x=>crypto.createHash('sha256').update(x).digest('hex');
function fail(m){throw new Error(m)}
function once(src,anchor,repl,label){const n=src.split(anchor).length-1;if(n!==1)fail(label+'_anchor_count_'+n);return src.replace(anchor,repl)}
function assertBaselineLocked(){if(BASELINE_LOCKED!==true)fail('baseline_not_locked');for(const k of ['base','exec','policy','mcp'])if(!/^[a-f0-9]{64}$/.test(BASELINE[k]||''))fail('baseline_invalid:'+k);return true}
function buildPolicyCandidate(source){const p=JSON.parse(source);if(p.operations?.[OPERATION]||p.typed_scopes?.some(s=>s?.action===ACTION))fail('already_present');if(p.schema_version!=='prhm.approval-policy.v1')fail('policy_schema_mismatch');p.version=POLICY_VERSION;p.operations[OPERATION]={level:3,risk:'high',requires_second_confirmation:true,one_time_use:true,requested_approver:'mohammad',expires_seconds:180,policy_version:POLICY_VERSION,rollback_reference:'host-action-v2:recovery-edge-topology-probe-v1:registration-rollback'};p.typed_scopes.push({tool:'host_action_v2_apply',project:'control_plane',environment:'production',action:ACTION,risk:'high',operation:OPERATION,principals:[{principal_id:'mohammad',roles:['mcp-operator']}]});return JSON.stringify(p,null,2)+'\n'}
function buildMcpCandidate(source){if(source.includes("'recovery_edge_topology_probe_v1'"))fail('already_present');const m=source.match(/const HostActionV2=z\.enum\(\[([\s\S]*?)\]\);/);if(!m)fail('mcp_enum_anchor_missing');const body=m[1].trimEnd();const sep=body.trim()?body.replace(/\s+$/,'').endsWith(',')?'':',':'';const next=body+sep+"'recovery_edge_topology_probe_v1'";return source.slice(0,m.index)+`const HostActionV2=z.enum([${next}]);`+source.slice(m.index+m[0].length)}
function buildBaseCandidate(source){if(source.includes('recovery_edge_topology_probe_v1'))fail('already_present');const anchor='});\nconst HOST_ACTION_V2_LEVEL3';if(!source.includes(anchor))fail('base_anchor_missing');const spec="  recovery_edge_topology_probe_v1: { operation: 'host_action.recovery_edge_topology_probe_v1', rollback: 'host-action-v2:recovery-edge-topology-probe-v1:registration-rollback' }\n";return source.replace(anchor,',\n'+spec+anchor)}
function buildExecCandidate(source,helperSha){if(!/^[a-f0-9]{64}$/.test(helperSha))fail('helper_sha_invalid');if(source.includes("recovery_edge_topology_probe_v1"))fail('already_present');const specAnchor='const ACTION_SPECS={';if(!source.includes(specAnchor))fail('exec_spec_anchor_missing');let out=source.replace(specAnchor,specAnchor+"recovery_edge_topology_probe_v1:{operation:'host_action.recovery_edge_topology_probe_v1',kind:'recovery_edge_topology_probe_v1'},");const applyAnchor='const applyHostActionV2Original=applyHostActionV2;';if(!out.includes(applyAnchor))fail('exec_apply_anchor_missing');const runner=`const RECOVERY_EDGE_TOPOLOGY_HELPER='${PATHS.helper}';
function applyRecoveryEdgeTopologyProbeV1(){const bytes=fs.readFileSync(RECOVERY_EDGE_TOPOLOGY_HELPER);const actual=require('node:crypto').createHash('sha256').update(bytes).digest('hex');if(actual!=='${helperSha}')throw new Error('recovery_edge_helper_sha_mismatch');const r=cp.execFileSync('/usr/local/bin/prhm-node',[RECOVERY_EDGE_TOPOLOGY_HELPER],{encoding:'utf8',timeout:45000,maxBuffer:256*1024});const parsed=JSON.parse(r);if(parsed?.ok!==true||parsed?.action!=='recovery_edge_topology_probe_v1'||parsed?.read_only!==true)throw new Error('recovery_edge_probe_result_invalid');return parsed}
`;
out=out.replace(applyAnchor,runner+applyAnchor);const dispatch="if(action==='recovery_edge_topology_probe_v1')return applyRecoveryEdgeTopologyProbeV1();";const idx=out.indexOf('return applyHostActionV2Original(action');if(idx<0)fail('exec_dispatch_anchor_missing');out=out.slice(0,idx)+dispatch+out.slice(idx);return out}
function buildRegistrationPlan(current){assertBaselineLocked();for(const k of ['base','exec','policy','mcp']){if(typeof current?.[k]!=='string')fail('source_missing:'+k);if(sha(current[k])!==BASELINE[k])fail('preimage_sha_mismatch:'+k)}const helper=Buffer.from(HELPER_B64,'base64');if(sha(helper)!==HELPER_SHA)fail('helper_sha_mismatch');const next={base:buildBaseCandidate(current.base),exec:buildExecCandidate(current.exec,HELPER_SHA),policy:buildPolicyCandidate(current.policy),mcp:buildMcpCandidate(current.mcp),helper:helper.toString('utf8')};return {ok:true,action:ACTION,next,post_sha256:Object.fromEntries(Object.entries(next).map(([k,v])=>[k,sha(v)])),application_mutation:false,database_mutation:false,node1_mutation:false}}
function preflight(){assertBaselineLocked();const current={base:fs.readFileSync(PATHS.base,'utf8'),exec:fs.readFileSync(PATHS.exec,'utf8'),policy:fs.readFileSync(PATHS.policy,'utf8'),mcp:fs.readFileSync(PATHS.mcp,'utf8')};return buildRegistrationPlan(current)}
module.exports={ACTION,OPERATION,POLICY_VERSION,PATHS,BASELINE,BASELINE_LOCKED,HELPER_SHA,assertBaselineLocked,buildPolicyCandidate,buildMcpCandidate,buildBaseCandidate,buildExecCandidate,buildRegistrationPlan,preflight};
